59	/// Returns a reduced ManaCost (generic portion lowered, colored requirements unchanged).
60	pub fn effective_spell_cost(state: &GameState, registry: &CardRegistry, card_id: CardId, base_cost: &ManaCost, caster: PlayerId) -> ManaCost {
61	    use crate::types::{ContinuousEffect, SpellFilter};
62	
63	    // Check if the card has a custom cost modification (e.g., Blasphemous Act).
64	    if let Some(behavior) = registry.get(card_id) {
65	        if let Some(modified) = behavior.modified_cost(state, registry) {
66	            return modified;
67	        }
68	    }
69	
70	    let card_data = registry.card_data(card_id);
71	    let is_creature = card_data.as_ref()
72	        .map(|d| d.card_types.contains(&CardType::Creature))
73	        .unwrap_or(false);
74	    let subtypes: Vec<String> = card_data.as_ref()
75	        .map(|d| d.subtypes.clone())
76	        .unwrap_or_default();
77	
78	    // Gather all ReduceCost effects from permanents the caster controls.
79	    let mut total_reduction: u32 = 0;
80	    for obj in state.objects.values() {
81	        if obj.zone != Zone::Battlefield || obj.controller != caster {
82	            continue;
83	        }
84	        if let Some(behavior) = registry.get(obj.card_id) {
85	            for effect in &behavior.card_data().continuous_effects {
86	                if let ContinuousEffect::ReduceCost { reduction, filter } = effect {
87	                    let applies = match filter {
88	                        SpellFilter::CreatureSpells => is_creature,
89	                        SpellFilter::CreatureWithSubtype(sub) => {
90	                            is_creature && subtypes.iter().any(|s| s == sub)
91	                        }
92	                    };
93	                    if applies {
